const fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('assert/strict');
const dir=path.resolve('备份/20261108-手部可编辑-'+Date.now());fs.mkdirSync(dir,{recursive:true});
const file='js/visual-layers.js',old=fs.readFileSync(file,'utf8');fs.writeFileSync(path.join(dir,'visual-layers.js'),old);
let next=old.replace('info(layer){return PE.classifyPart(layer?.name);}',"info(layer){return PE.classifyPart(String(layer?.name||'').replace(/ 描边$/, ''));}");
const marker="      if(partLabel==='用户')label.textContent='用户 · '+slot;";
assert(next.includes(marker));next=next.replace(marker,"      const baseName=l.name.replace(/ 描边$/, ''),bodyLabel={head:'头部',body:'身体',hand:'前手','hand 2':'后手'}[baseName];\n      if(bodyLabel)label.textContent=bodyLabel+(l.name.endsWith(' 描边')?'描边':'底色');\n"+marker);
assert.notEqual(next,old);fs.writeFileSync(file,next);
(async()=>{const url='http://127.0.0.1:8765/api/project?id=draft-7278d7c9-a753-4c98-bf8b-d7c2d45119ba';const r=await fetch(url),raw=Buffer.from(await r.arrayBuffer()),p=JSON.parse(raw),before=structuredClone(p);fs.writeFileSync(path.join(dir,'before.json'),raw);fs.writeFileSync(path.join(dir,'metadata.json'),JSON.stringify({url,etag:r.headers.get('etag'),sha256:crypto.createHash('sha256').update(raw).digest('hex')}));let count=0;for(const l of p.layers)if(/^hand(?: 2)?(?: 描边)?$/.test(l.name)){assert(!l.inheritedBase);l.referenceOnly=false;l.locked=false;count++;}assert.equal(count,48);for(let i=0;i<p.layers.length;i++)assert.deepEqual(p.layers[i].frameData,before.layers[i].frameData);fs.writeFileSync(path.join(dir,'candidate.json'),JSON.stringify(p));const put=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json','X-Pixel-Editor':'1','If-Match':r.headers.get('etag')},body:JSON.stringify(p)});assert(put.ok,await put.text());const saved=await(await fetch(url)).json();assert.deepEqual(saved,p);fs.writeFileSync(path.join(dir,'verified.json'),JSON.stringify(saved));console.log(dir,'48 hand layers unlocked; all pixels unchanged');})().catch(e=>{console.error(e);process.exitCode=1});
